from fractions import Fraction

def v(t):
    return 3 * t**2 - 12 * t + 9

def a(t):
    return 6 * t - 12

for k in range(9):
    t = Fraction(k, 2)
    print(f"t = {t}: v = {v(t)}, a = {a(t)}")
    if v(t) > 0:
        print("  v > 0, so moving forward")
    elif v(t) < 0:
        print("  v < 0, so moving backward")
    else:
        print("  v = 0, so stopped for an instant")
    if v(t) * a(t) > 0:
        print("  v and a have the same sign, so speeding up")
    elif v(t) * a(t) < 0:
        print("  v and a have opposite signs, so slowing down")
    else:
        print("  v or a is 0, so neither")

