from fractions import Fraction

a = Fraction(1, 1000)
b = Fraction(3, 10)

def cost(x):
    return a * x**3 - b * x**2 + 40 * x + 1000

def marginal(x):
    return 3 * a * x**2 - 2 * b * x + 40

def second(x):
    return 6 * a * x - 2 * b

for x in [50, 100, 200, 400]:
    print(f"x = {x}")
    print(f"  C'(x) = {marginal(x):.2f} dollars per unit")
    print(f"  next unit, C(x + 1) - C(x) = {cost(x + 1) - cost(x):.2f}")
    print(f"  average cost C(x)/x = {cost(x) / x:.2f}")
    if second(x) > 0:
        print(f"  C''(x) = {second(x):.3f} > 0, so marginal cost is rising")
    elif second(x) < 0:
        print(f"  C''(x) = {second(x):.3f} < 0, so marginal cost is falling")
    else:
        print("  C''(x) = 0, so marginal cost is at its turning point")
